export const CHAPTERS = [
 {
  "name": "Shove",
  "rule": "Shove the next gear in from a lever at the rim. Gears of one pitch that touch mesh; three or more in a chain make a train. The goal asks for trains of a length."
 },
 {
  "name": "Pitches",
  "rule": "Gears of different pitches (tooth sizes) never mesh: grow a train of each."
 },
 {
  "name": "Shear and jam",
  "rule": "A shove moves a whole line and can pull a train apart; three gears of one pitch in a triangle jam, and a jammed train doesn't count."
 },
 {
  "name": "The hold",
  "rule": "Swap sets the next gear aside or brings the held one back, once a turn: the order is yours to plan."
 },
 {
  "name": "Idlers",
  "rule": "The black idler meshes every pitch: it joins trains of different pitches into one, and it can close a ring and jam."
 },
 {
  "name": "Jewels",
  "rule": "A jewel counts only under a train that turns: cover every jewel."
 },
 {
  "name": "Bridges",
  "rule": "A bridge shows two pitches and meshes both, so it fuses their trains into one: keep the trains you need apart."
 },
 {
  "name": "Studs",
  "rule": "A stud (a rivet) never moves and ends a line: a shove stops short of it."
 },
 {
  "name": "The workshop",
  "rule": "Everything together: pitches, the hold, idlers, jewels, bridges and studs on one plate."
 }
];
